package os.aios.core.automation;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
/** Durable task grants and resource lease generations shared by scheduled paths. */
final class PolicyLedger{
 private final AutomationStore store;PolicyLedger(AutomationStore s){store=s;}
 synchronized JSONObject put(JSONObject p)throws Exception{new os.aios.runtime.TaskAuthorization(p);ContentValues v=new ContentValues();v.put("id",p.getString("id"));v.put("doc",p.toString());v.put("revoked",0);v.put("updated_at",System.currentTimeMillis());store.database().insertWithOnConflict("task_authorizations",null,v,SQLiteDatabase.CONFLICT_REPLACE);return p;}
 synchronized JSONObject get(String id)throws Exception{try(Cursor c=store.database().rawQuery("SELECT doc,revoked FROM task_authorizations WHERE id=?",new String[]{id})){if(!c.moveToFirst()||c.getInt(1)!=0)throw new SecurityException("Task authorization missing or revoked");return new JSONObject(c.getString(0));}}
 synchronized void require(String id,String capability,String resource,long planVersion)throws Exception{new os.aios.runtime.TaskAuthorization(get(id)).require(capability,resource,planVersion,System.currentTimeMillis());}
 synchronized JSONObject revoke(String id)throws JSONException{store.database().execSQL("UPDATE task_authorizations SET revoked=1,updated_at=? WHERE id=?",new Object[]{System.currentTimeMillis(),id});store.database().delete("resource_leases","owner LIKE ?",new String[]{id+":%"});return new JSONObject().put("id",id).put("revoked",true);}
 synchronized JSONObject acquire(String authorization,String owner,String resource,long ttl)throws Exception{require(authorization,"scheduler.execute",resource,1);SQLiteDatabase d=store.database();long now=System.currentTimeMillis(),generation=1;try(Cursor c=d.rawQuery("SELECT owner,generation,expires_at FROM resource_leases WHERE resource=?",new String[]{resource})){if(c.moveToFirst()){if(c.getLong(2)>now&&!c.getString(0).equals(owner))throw new IllegalStateException("Resource busy: "+resource);generation=c.getLong(1)+1;}}String id=UUID.randomUUID().toString();long expires=now+Math.max(5000,Math.min(3600000,ttl));d.execSQL("INSERT OR REPLACE INTO resource_leases(resource,id,owner,generation,expires_at) VALUES(?,?,?,?,?)",new Object[]{resource,id,owner,generation,expires});return new JSONObject().put("id",id).put("owner",owner).put("resource",resource).put("generation",generation).put("expires_at",expires);}
 synchronized void release(String owner){store.database().delete("resource_leases","owner=?",new String[]{owner});}
}
